# -*- coding: utf-8 -*-
"""
Object that allows you to run keywords simultaneously, while maintaining robot logs

:copyright: Nokia Networks
:author: MN_RAN_PZ_KRK_TAG
:contact: I_MN_RAN_PZ_KRK_TAG@internal.nsn.com
:maintainer: I_MN_RAN_PZ_KRK_TAG@internal.nsn.com
"""
import funcsigs
from functools import partial
from robot.libraries.BuiltIn import BuiltIn
try:
    from inspect import getfullargspec as get_args
except ImportError:
    from inspect import getargspec as get_args
from taf.rfrl.utilities.robot.RobotWrapper import _disable_cached_logs


def run_as_robot_kw(function, obj=None, custom_repr_name=None, *args, **kwargs):
    """
    :author: jakub.siluch@nokia.com
    :maintainer: jakub.siluch@nokia.com
    :note: Please contact with maintainer with any issue of this KW(prototype version)
    :param function: instance of method that want to be perform
    :param custom_repr_name: if provided, the object repr will be change in log.html
    :param obj: optional argument, object instance that contains the method, KW should set proper object, if not, please
    set it manually
    :param args: *args to be passed to function
    :param kwargs: all function parameter should be passed via kwargs, also there should be passed **kwargs of function
    Example of execution:
    class test(object):

        def test_func(self, arg, arg2, arg3=3, arg4=4, *args, **kwargs):
        pass
    Normal execution: convert_python_function_to_robot_kw(test().test_func, arg=2, arg2=3)
    Execution with args: convert_python_function_to_robot_kw(test().test_func(), None, None, 123, 321, 222, 10, 11, 12,
    13, test=2, test2=[1, 2, "3,", True, False, [1, 2]])
    It will assign arg=2 arg2=3 arg3=3 arg4=4, *args: 123 321, **kwargs: test=2 test2=[1, 2, '3,', True, False, [1, 2]]
    """

    def _get_default_args_values(func):
        func_args = funcsigs.signature(func).parameters
        args_spec = get_args(func)
        return {arg: func_args[arg].default if func_args[arg].default is not funcsigs._empty else None
                for arg in list(func_args) if arg is not args_spec[1] and arg is not args_spec[2]}

    def _prepare_args(func, kwarguments):
        func_default_args = _get_default_args_values(func=func)
        for arg in list(kwarguments):
            if arg in list(func_default_args):
                func_default_args[arg] = kwarguments[arg]
                del kwarguments[arg]
        return func_default_args

    class dump:

        def __init__(self, name, func, class_obj, func_args, func_args_values, args, kwargs):
            self.name = name if name == "" else name + "."
            self.func = func
            self.class_obj = class_obj
            self.args = list(func_args_values) + list(args)
            self.func_args = func_args
            self.kwargs = kwargs

        def __repr__(self):
            func_param_list = ["{}={}".format(arg, self.func_args[arg]) for arg in list(self.func_args)]
            func_param = ", func_args: " + "   ".join(func_param_list) if len(func_param_list) != 0 else ""
            func_args_list = ["{}".format(arg) for arg in list(self.args)[len(self.func_args):]]
            func_args = ", *args: " + "   ".join(func_args_list) if len(func_args_list) != 0 else ""
            func_kwargs_list = ["{}={}".format(arg, self.kwargs[arg]) for arg in list(self.kwargs)]
            func_kwargs = ", **kwargs: " + "   ".join(func_kwargs_list) if len(func_kwargs_list) != 0 else ""
            if custom_repr_name is None:
                return self.name + str(self.func.__name__) + func_param + func_args + func_kwargs
            return custom_repr_name + func_param + func_args + func_kwargs

        def convert_python_function_to_robot_kw(self):
            if self.class_obj is not None:
                try:
                    func_name = self.func.__name__
                    class_name = self.class_obj.__class__.__name__
                    self.func = getattr(self.class_obj, func_name) if func_name.startswith("__") is False else \
                        getattr(self.class_obj, "_{}{}".format(class_name, func_name))
                except AttributeError:
                    inherited_class_name = self.class_obj.__class__.__bases__[0].__name__
                    self.func = getattr(self.class_obj, "_{}{}".format(inherited_class_name, func_name))
            return partial(self.func, *self.args, **self.kwargs)

        def _(self):
            try:
                return self.convert_python_function_to_robot_kw()()
            except Exception as e:
                return e
    _disable_cached_logs()

    if obj is None:
        try:
            obj = function.__self__
        except AttributeError:
            obj = None
    fun_args = _prepare_args(func=function, kwarguments=kwargs) if kwargs else {}
    if obj is not None:
        result = BuiltIn().run_keyword("BuiltIn.call_method", dump(obj.__class__.__name__, function, obj, fun_args,
                                                                   func_args_values=fun_args.values(),
                                                                   args=args, kwargs=kwargs), "_")
    else:
        result = BuiltIn().run_keyword("BuiltIn.call_method", dump("", function, obj, fun_args,
                                                                   func_args_values=fun_args.values(),
                                                                   args=args, kwargs=kwargs), "_")
    if isinstance(result, Exception) is True:
        raise result
    return result
